          "Because it's now a provincial matter, the specific fine amounts, challan procedures, and enforcement details can differ between provinces even though the underlying 1965 framework is shared. If you're dealing with a specific challan or penalty, check the current schedule for your province rather than assuming it matches what you've heard about another one.",
