          "Since the 18th Amendment also devolved education to the provinces, implementation now runs through provincial legislation and administration rather than one federal statute — Islamabad Capital Territory and each province have their own compulsory education laws and enforcement mechanisms, so the specific complaint pathway depends on where the school is located.",
