          "For most school-related grievances, the practical path is: document the dispute in writing (dates, communications with the school, any policy the school itself has published), escalate first through the school's own grievance procedure if one exists, and then to the relevant provincial education authority — courts are generally a later resort, reserved for serious or unresolved matters, especially given how fact-specific and administratively-handled most of these disputes are.",
