          "Because navigating unfamiliar legal, consular, and labor-ministry systems simultaneously is genuinely difficult under stress, it helps to write down exactly what happened, when, and who's involved before you contact any of these — that same organized summary is useful whether you end up presenting it to your embassy, a labor ministry, or a local lawyer.",
