          "This is a meaningful difference from countries that still track English common law more closely — Singapore's legal system has had over three decades to diverge and develop its own case law on commercial disputes, contracts, and other core common-law areas, so citing older or purely English precedent without checking Singapore's own case law can be a mistake.",
