          "Germany's civil law tradition centers on the Bürgerliches Gesetzbuch (BGB), enacted on 1 January 1900 and still the principal codification of German private law today — structured into five books covering the General Part, obligations, property (things), family law, and succession. Notably, the BGB survived the Nazi era and was reaffirmed as federal law in West Germany after 1945, specifically under Articles 123 and 125 of the Basic Law that followed — a rare example of a private-law code outlasting the political system that once governed alongside it.",
          "That Basic Law — the Grundgesetz — was adopted in 1949 as West Germany's constitution and extended nationwide after reunification in 1990. It was deliberately built around inviolable human dignity, entrenched fundamental rights, federalism, and the Rechtsstaat (rule-of-law) principle — a direct constitutional response to the Nazi era, designed structurally to make a repeat abuse of state power far harder. This history is why German constitutional law places unusually strong emphasis on human dignity as a starting principle, not just one right among many.",
