          "Germany is also well known for particularly strong statutory labor protections: works councils with real co-determination rights (Mitbestimmung) in company decisions, strict dismissal protection under specific statutes, and extensive collective bargaining coverage — generally requiring more procedural care from employers than common-law jurisdictions with more flexible at-will norms, similar in spirit to France but with its own distinct statutory mechanisms.",
