        paragraphs: [
          "Spain's legal system is built on the civil law tradition, anchored by the Código Civil (Civil Code) of 1889 — a code heavily influenced by the French Napoleonic Civil Code of 1804 — which still governs the core of Spanish private law: family relations, property rights, and contractual obligations, despite having been amended many times since. Above it sits the Spanish Constitution of 1978, approved as Spain transitioned to democracy after the Franco era, which established Spain as a social and democratic state governed by the rule of law and created a distinctive quasi-federal structure of 17 autonomous communities, each with its own regional government and, in several cases, its own regional civil law variations (particularly in Catalonia, the Basque Country, and other regions with historical civil-law traditions, foral law).",
          "This regional layer matters practically: some property, inheritance, and family law questions in Spain are governed not just by the national Código Civil but by regional foral (charter) law specific to certain autonomous communities — a genuinely different situation than in most centralized civil-law countries.",
        ],
