          "Religious Courts (Peradilan Agama) coexist with the general national court system — a structural continuity from the Dutch colonial period itself, when colonial authorities specifically restricted qadi (Islamic judge) jurisdiction to marriage, divorce, and inheritance while subordinating Islamic courts to the colonial court hierarchy. As of 2018, there were 441 Religious Courts nationwide, with jurisdiction limited to family law, inheritance, wakaf (religious endowment), and shadaqah (religious charitable giving) — not general civil or criminal matters.",
