          "For business, employment, and most civil matters outside Aceh's special provisions, Indonesia's national civil and commercial codes (rooted in that Dutch colonial civil-law framework) apply broadly, though implementation and enforcement can vary regionally in practice — another reason to verify current, region-specific detail with an Indonesia-qualified lawyer rather than relying on a national-level summary alone.",
